// This function expects msg.payload from MQTT to be a JSON string or object.
// Example MQTT payload: {"battery_percentage": 50.12, "timestamp": "2025-10-28 03:00:00"}

let parsedPayload = msg.payload;

// If the payload is a string, try to parse it as JSON
if (typeof msg.payload === 'string') {
    try {
        parsedPayload = JSON.parse(msg.payload);
    } catch (e) {
        node.error("Function Node: Failed to parse JSON payload: " + e.message, msg);
        return null; // Stop flow if parsing fails
    }
}

let batteryPercentage = parsedPayload.battery_percentage;

// Validate if batteryPercentage is a valid number
if (typeof batteryPercentage !== 'number' || isNaN(batteryPercentage)) {
    node.warn("Function Node: Invalid battery_percentage received: " + batteryPercentage, msg);
    // Optionally, you could set a default value or return null to stop the flow
    return null; // Stop flow if data is invalid
}

// Prepare the data for InfluxDB 2.x output node
msg.payload = {
    data: {
        battery_percentage: batteryPercentage // This is the field value
    },
    measurement: "mqtt_consumer", // This matches your Grafana query assumption
    tags: {
        topic: "battery/status" // Add topic as a tag for filtering in Grafana
    }
};
// InfluxDB will usually add its own timestamp if not provided, which is often fine.

return msg; // CRITICAL: This line must be present to pass the message to the next nodes
